ValidationRule.errorConditionFormula:
OR(
    AND(
        ISBLANK(Candidate__c),
        NOT(ISBLANK(Portal_Contact__c))
    ),
    AND(
        NOT(ISBLANK(Candidate__c)),
        OR(
            ISBLANK(Portal_Contact__c),
            Portal_Contact__c <> Candidate__r.Contact__c
        )
    )
)
